const input = [2, 1, 2, 3, 1];
const result = uniqueInOrder(input);
assert(Array.isArray(result), '应返回数组');
assertEqual(JSON.stringify(result), '[2,1,3]');
assertEqual(JSON.stringify(input), '[2,1,2,3,1]');
